@st.composite
def _version_str(draw):
    inner = st.text(
        alphabet=st.characters(whitelist_categories=None, blacklist_characters='!+-ABCDEHILOPRSTVW_abcdehiloprstvw'),
        min_size=1,
        max_size=4,
    ).example("1.2.3")
    return draw(st.text(alphabet=st.characters(whitelist_categories=None), min_size=0, max_size=8)) + inner + draw(st.text(alphabet=st.characters(whitelist_categories=None), min_size=0, max_size=8))

strategy = st.tuples(_version_str())
